import functools


def announce(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        print("called", fn.__name__)
        return fn(*args, **kwargs)
    return wrapper


def repeat(times):
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            return [fn(*args, **kwargs) for _ in range(times)]
        return wrapper
    return decorate


@announce
@repeat(2)
def spark(x):
    return x * 10


print(spark(3))
print(spark.__name__)

