from typing import Optional


def tally(words: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return counts


def first_long(words: list[str], limit: int) -> Optional[str]:
    for w in words:
        if len(w) > limit:
            return w
    return None


print(tally(["ash", "ore", "ash"]))
print(first_long(["ash", "ember"], 3))
print(first_long(["ash"], 3))
print(first_long.__annotations__["return"])

