import functools


def clamp_to(limit):
    def decorate(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            result = fn(*args, **kwargs)
            return result if result <= limit else limit
        return wrapper
    return decorate


@clamp_to(100)
def total(numbers: list[int]) -> int:
    return sum(numbers)

