from typing import Optional


def first_over(values: list[int], limit: int) -> Optional[int]:
    for value in values:
        if value > limit:
            return value
    return None


def probe(name, values, limit):
    return [first_over(values, limit), str(first_over.__annotations__[name])]

import functools


class Chunks:
    def __init__(self, values, size):
        self.values = values
        self.size = size
        self.at = 0

    def __iter__(self):
        return self

    def __next__(self):
        if self.at + self.size > len(self.values):
            raise StopIteration
        chunk = self.values[self.at:self.at + self.size]
        self.at += self.size
        return chunk


def sorted_result(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        return sorted(fn(*args, **kwargs))
    return wrapper


@sorted_result
def chunk_sums(values: list[int], size: int) -> list[int]:
    return [sum(chunk) for chunk in Chunks(values, size)]
